"""反证覆盖、证据引用与宿主计算的置信度；模型不能自行放行任务。"""

from dataclasses import dataclass
from datetime import datetime
from enum import StrEnum
from typing import Annotated, Literal
from uuid import UUID

from pydantic import Field, model_validator

from app.agent.investigation import AgentConclusion, EvidenceClaim, InvestigationSpec
from app.agent.models import ToolCall
from app.tasks.workflow_models import TaskSnapshot
from app.tools.models import JsonObject, ToolModel

REVIEW_TOOLS = frozenset({"query_metrics", "query_logs", "query_traces", "get_recent_changes"})
REVIEW_ACTOR = "codex-reviewer"


def within_review_scope(call: ToolCall, spec: InvestigationSpec) -> bool:
    values = call.function.parsed_arguments
    if values.get("service_name") != spec.service_name:
        return False
    try:
        end = datetime.fromisoformat(str(values["end"]))
        if call.function.name == "get_recent_changes":
            lookback = values.get("lookback_seconds")
            return (
                end == spec.end
                and type(lookback) is int
                and 0 < lookback <= (spec.end - spec.start).total_seconds()
            )
        start = datetime.fromisoformat(str(values["start"]))
        return spec.start <= start < end <= spec.end
    except (ValueError, TypeError, KeyError):
        return False


class AlternativeCause(StrEnum):
    NETWORK = "network"
    REDIS = "redis"
    RELEASE = "release"
    THIRD_PARTY = "third_party"


class ReviewCheck(EvidenceClaim):
    alternative: AlternativeCause
    outcome: Literal["not_supported", "contradicts", "inconclusive"]


class ReviewReport(ToolModel):
    checks: Annotated[tuple[ReviewCheck, ...], Field(min_length=4, max_length=4)]

    @model_validator(mode="after")
    def complete_coverage(self) -> "ReviewReport":
        if {item.alternative for item in self.checks} != set(AlternativeCause):
            raise ValueError("必须分别反证网络、Redis、发布与第三方依赖")
        return self

    @property
    def evidence_ids(self) -> frozenset[UUID]:
        return frozenset(reference for item in self.checks for reference in item.evidence_ids)

    @property
    def verdict(self) -> str:
        if any(item.outcome == "contradicts" for item in self.checks):
            return "contradicted"
        if any(item.outcome == "inconclusive" for item in self.checks):
            return "inconclusive"
        return "clear"


class ReviewInput(ToolModel):
    spec: InvestigationSpec
    conclusion_evidence_id: UUID
    conclusion: AgentConclusion
    # 主 Agent 原始引用快照是待复核的数据，而非 Reviewer 查询产生的独立证据。
    evidence_snapshots: tuple[JsonObject, ...]


class ReviewDecision(ToolModel):
    conclusion_evidence_id: UUID
    original_confidence: float = Field(ge=0, le=1, allow_inf_nan=False)
    conclusion: AgentConclusion
    report: ReviewReport
    observed_ids: Annotated[tuple[UUID, ...], Field(min_length=1)]
    steps: int = Field(ge=1, le=100)


def adjusted_conclusion(original: AgentConclusion, report: ReviewReport) -> AgentConclusion:
    # 置信度只由宿主按固定规则调整，不把模型主观评分当成执行授权。
    delta = 0.1 if report.verdict == "clear" else -0.2 if report.verdict == "contradicted" else 0
    return original.model_copy(
        update={"confidence": round(min(1.0, max(0.0, original.confidence + delta)), 10)}
    )


@dataclass(frozen=True)
class ReviewRequest:
    task: TaskSnapshot
    spec_json: str
    conclusion_evidence_id: str


@dataclass(frozen=True)
class ReviewResult:
    evidence_id: str
    decision_json: str

"""支付场景 Fake Reviewer 根据真实返回快照判断，不预先写死复核结论。"""

import json
import math

from app.agent.models import ChatMessage, ChatRequest, ChatResponse, FunctionCall, ToolCall
from app.agent.reviewer.models import AlternativeCause, ReviewCheck, ReviewInput, ReviewReport
from app.tools.models import DispatchResult, DispatchStatus, JsonObject


def review_response(request: ChatRequest) -> ChatResponse:
    value = ReviewInput.model_validate_json(request.messages[1].content or "{}")
    results = [
        DispatchResult.model_validate_json(item.content or "{}")
        for item in request.messages
        if item.role == "tool"
    ]
    if len(results) < 2:
        index = len(results)
        parameters: JsonObject = {"service_name": value.spec.service_name}
        if index == 0:
            parameters.update(start=value.spec.start.isoformat(), end=value.spec.end.isoformat())
        else:
            parameters.update(
                end=value.spec.end.isoformat(),
                lookback_seconds=math.floor((value.spec.end - value.spec.start).total_seconds()),
            )
        return ChatResponse(
            id=f"review-query-{index}",
            model="fake-reviewer",
            finish_reason="tool_calls",
            message=ChatMessage(
                role="assistant",
                tool_calls=(
                    ToolCall(
                        id=f"review-{index}",
                        function=FunctionCall(
                            name="query_traces" if index == 0 else "get_recent_changes",
                            arguments=json.dumps(parameters),
                        ),
                    ),
                ),
            ),
        )
    if any(
        item.status is not DispatchStatus.SUCCEEDED or item.evidence_id is None for item in results
    ):
        return ChatResponse(
            id="review-refusal",
            model="fake-reviewer",
            finish_reason="stop",
            message=ChatMessage(role="assistant", refusal="独立证据不足"),
        )
    traces = (results[0].result or {}).get("traces", [])
    spans: list[JsonObject] = []
    if isinstance(traces, list):
        for trace in traces:
            if not isinstance(trace, dict):
                continue
            trace_spans = trace.get("spans", [])
            if isinstance(trace_spans, list):
                spans.extend(span for span in trace_spans if isinstance(span, dict))
    checks = []
    for alternative, operation in (
        (AlternativeCause.NETWORK, "TCP connect"),
        (AlternativeCause.REDIS, "Redis GET"),
        (AlternativeCause.THIRD_PARTY, "第三方支付请求"),
    ):
        samples = [span for span in spans if span.get("operation") == operation]
        contradicted = any(
            span.get("result_code") not in {"ok", "200", "success"} for span in samples
        )
        checks.append(
            ReviewCheck(
                alternative=alternative,
                outcome="contradicts"
                if contradicted
                else "not_supported"
                if samples
                else "inconclusive",
                statement=f"{operation} 观测出现失败，反驳仅归因于连接池的结论。"
                if contradicted
                else f"查询范围内 {operation} 样本正常，暂未发现该替代原因。"
                if samples
                else f"缺少 {operation} 样本，不能排除该原因。",
                evidence_ids=(results[0].evidence_id,),  # type: ignore[arg-type]
            )
        )
    events = (results[1].result or {}).get("events", [])
    checks.append(
        ReviewCheck(
            alternative=AlternativeCause.RELEASE,
            outcome="not_supported" if events else "inconclusive",
            statement="近期变更已重新查询，暂未找到与原发布线索冲突的其他变更；因果关系仍待调查。"
            if events
            else "缺少变更样本，不能排除其他发布原因。",
            evidence_ids=(results[1].evidence_id,),  # type: ignore[arg-type]
        )
    )
    return ChatResponse(
        id="review-report",
        model="fake-reviewer",
        finish_reason="stop",
        message=ChatMessage(
            role="assistant", content=ReviewReport(checks=tuple(checks)).model_dump_json()
        ),
    )

"""支付 5xx 的有限离线 LLM 脚本，只引用实际 Tool 返回的证据。"""

import json
import math
from functools import partial
from typing import Literal

from app.agent.fake import FakeLLM, ScriptedChatStep
from app.agent.investigation import AgentConclusion, EvidenceClaim, InvestigationSpec
from app.agent.models import ChatMessage, ChatRequest, ChatResponse, FunctionCall, ToolCall
from app.tools.models import DispatchResult, DispatchStatus, JsonObject

PAYMENT_TOOLS = ("get_service_context", "get_recent_changes", "query_metrics", "query_logs")


def script_spec(request: ChatRequest) -> InvestigationSpec:
    content = request.messages[1].content
    assert content is not None
    return InvestigationSpec.model_validate_json(content)


def tool_response(request: ChatRequest, index: int) -> ChatResponse:
    spec = script_spec(request)
    parameters: JsonObject = {"service_name": spec.service_name}
    if index == 1:
        parameters.update(
            lookback_seconds=math.ceil((spec.end - spec.start).total_seconds()),
            end=spec.end.isoformat(),
        )
    elif index >= 2:
        parameters.update(start=spec.start.isoformat(), end=spec.end.isoformat())
    return ChatResponse(
        id=f"fake-turn-{index}",
        model="fake-payment-investigator",
        finish_reason="tool_calls",
        message=ChatMessage(
            role="assistant",
            content="按计划查询下一项事实，再结合返回证据继续判断。",
            tool_calls=(
                ToolCall(
                    id=f"payment-query-{index}",
                    function=FunctionCall(
                        name=PAYMENT_TOOLS[index], arguments=json.dumps(parameters)
                    ),
                ),
            ),
        ),
    )


def conclusion_response(request: ChatRequest) -> ChatResponse:
    results = [
        DispatchResult.model_validate_json(message.content or "{}")
        for message in request.messages
        if message.role == "tool"
    ]
    if len(results) != 4 or any(
        item.status is not DispatchStatus.SUCCEEDED or item.evidence_id is None for item in results
    ):
        return ChatResponse(
            id="fake-insufficient",
            model="fake-payment-investigator",
            finish_reason="stop",
            message=ChatMessage(role="assistant", refusal="查询失败，证据不足以支持结论"),
        )
    snapshots = [item.result or {} for item in results]
    if script_spec(request).service_name != "payment-service":
        return ChatResponse(
            id="fake-out-of-scope",
            model="fake-payment-investigator",
            finish_reason="stop",
            message=ChatMessage(role="assistant", refusal="离线脚本只支持支付验收场景"),
        )
    if not all(
        snapshots[index].get(key) for index, key in enumerate(("nodes", "events", "series", "logs"))
    ):
        return ChatResponse(
            id="fake-empty",
            model="fake-payment-investigator",
            finish_reason="stop",
            message=ChatMessage(role="assistant", refusal="样例所需事实缺失，不能下结论"),
        )
    ids = [item.evidence_id for item in results]
    assert all(value is not None for value in ids)
    claims = tuple(
        EvidenceClaim(statement=statement, evidence_ids=(evidence_id,))
        for statement, evidence_id in zip(
            (
                "认知图已提供 payment-service 的运行资源与依赖关系，需注意关系新鲜度。",
                "查询时间窗内存在近期变更，需要继续验证其与故障的因果关系。",
                "查询窗口内返回了 payment-service 的 5xx 指标。",
                "日志返回数据库连接池等待超时。",
            ),
            ids,
            strict=True,
        )
        if evidence_id is not None
    )
    conclusion = AgentConclusion(
        root_cause=EvidenceClaim(
            statement="数据库连接池等待超时是当前故障线索，近期发布为待验证的诱因。",
            evidence_ids=tuple(value for value in ids[1:] if value is not None),
        ),
        findings=claims,
        confidence=0.7,
        uncertainties=("近期发布与故障的因果关系仍需核实；生产恢复以独立 Verifier 结果为准。",),
    )
    return ChatResponse(
        id="fake-conclusion",
        model="fake-payment-investigator",
        finish_reason="stop",
        message=ChatMessage(role="assistant", content=conclusion.model_dump_json()),
    )


def invalid_conclusion_response(request: ChatRequest) -> ChatResponse:
    response = conclusion_response(request)
    data = json.loads(response.message.content or "{}")
    data["root_cause"]["evidence_ids"] = ["00000000-0000-0000-0000-000000000001"]
    return response.model_copy(
        update={
            "message": ChatMessage(role="assistant", content=json.dumps(data, ensure_ascii=False))
        }
    )


def payment_llm(mode: Literal["valid", "invalid"] = "valid") -> FakeLLM:
    steps = [ScriptedChatStep(partial(tool_response, index=index)) for index in range(4)]
    if mode == "invalid":
        steps.append(ScriptedChatStep(invalid_conclusion_response))
    else:
        steps.append(ScriptedChatStep(conclusion_response))
    return FakeLLM(steps)

"""登录 HTTP 适配与整个 /api 命名空间的会话门禁。"""

import hmac
from datetime import datetime
from typing import Annotated, Literal

from fastapi import APIRouter, Depends, Header, HTTPException, Request, Response
from pydantic import BaseModel, ConfigDict, Field, SecretStr
from sqlalchemy.exc import SQLAlchemyError
from starlette.responses import JSONResponse
from starlette.types import ASGIApp, Message, Receive, Scope, Send

from app.auth.config import AuthConfig
from app.auth.identity import Principal
from app.auth.service import AuthService, LoginRejected
from app.config import Settings
from app.db.session import Database

router = APIRouter(prefix="/api/auth", tags=["登录与会话"])
SAFE_METHODS = frozenset({"GET", "HEAD", "OPTIONS"})
DOCUMENT_PATHS = frozenset({"/docs", "/docs/oauth2-redirect", "/redoc", "/openapi.json"})


def get_auth_service(request: Request) -> AuthService:
    settings: Settings = request.app.state.settings
    database: Database | None = getattr(request.app.state, "database", None)
    if settings.auth_config is None or database is None:
        raise HTTPException(503, "登录需要 AUTH_CONFIG 和 DATABASE_URL")
    return AuthService(database, settings.auth_config)


def require_principal(request: Request) -> Principal:
    principal: object = getattr(request.state, "principal", None)
    if not isinstance(principal, Principal):
        raise HTTPException(401, "请先登录")
    return principal


CurrentPrincipal = Annotated[Principal, Depends(require_principal)]


def check_origin(request: Request, config: AuthConfig) -> bool:
    origin = request.headers.get("origin")
    return (origin is None or origin == config.public_origin) and request.headers.get(
        "sec-fetch-site"
    ) != "cross-site"


class SessionMiddleware:
    def __init__(self, app: ASGIApp) -> None:
        self.app = app

    async def __call__(self, scope: Scope, receive: Receive, send: Send) -> None:
        path = scope.get("path", "")
        if scope["type"] not in {"http", "websocket"} or not (
            path == "/api" or path.startswith("/api/") or path.rstrip("/") in DOCUMENT_PATHS
        ):
            await self.app(scope, receive, send)
            return
        # 此阶段不开放 WebSocket，避免将来新增路由遗漏会话门禁。
        if scope["type"] == "websocket":
            await send({"type": "websocket.close", "code": 1008})
            return
        request = Request(scope, receive)
        error: HTTPException | None = None
        settings: Settings = request.app.state.settings
        login = path == "/api/auth/login" and request.method == "POST"
        try:
            if login:
                if settings.auth_config is None:
                    raise HTTPException(503, "登录需要 AUTH_CONFIG 和 DATABASE_URL")
                if (
                    not check_origin(request, settings.auth_config)
                    or request.headers.get("x-ops-login") != "1"
                ):
                    raise HTTPException(403, "登录来源校验失败，请携带 X-Ops-Login: 1")
            else:
                if settings.auth_config is None:
                    raise HTTPException(401, "请先登录")
                cookie = request.cookies.get(settings.auth_config.cookie_name, "")
                if not cookie:
                    raise HTTPException(401, "请先登录")
                service = get_auth_service(request)
                principal = await service.authenticate(cookie)
                if principal is None:
                    raise HTTPException(401, "会话无效或已过期，请重新登录")
                request.state.principal = principal
                if request.method not in SAFE_METHODS and (
                    not check_origin(request, settings.auth_config)
                    or not hmac.compare_digest(
                        request.headers.get("x-csrf-token", "").encode(),
                        principal.csrf_token.encode(),
                    )
                ):
                    raise HTTPException(403, "CSRF 校验失败")
        except HTTPException as caught:
            error = caught
        except (SQLAlchemyError, OSError, TimeoutError):
            error = HTTPException(503, "会话存储暂时不可用")
        if error is not None:
            await JSONResponse(
                {"detail": error.detail},
                status_code=error.status_code,
                headers={"Cache-Control": "no-store"},
            )(scope, receive, send)
            return

        async def no_cache(message: Message) -> None:
            if message["type"] == "http.response.start":
                headers = list(message.get("headers", []))
                headers.append((b"cache-control", b"no-store"))
                message["headers"] = headers
            await send(message)

        await self.app(scope, receive, no_cache)


class LoginRequest(BaseModel):
    model_config = ConfigDict(extra="forbid", hide_input_in_errors=True)
    username: str = Field(min_length=1, max_length=200, strict=True)
    password: SecretStr = Field(min_length=1, max_length=256)


class SessionResponse(BaseModel):
    actor: str
    expires_at: datetime
    csrf_token: str


def session_response(principal: Principal) -> SessionResponse:
    return SessionResponse(
        actor=principal.actor, expires_at=principal.expires_at, csrf_token=principal.csrf_token
    )


@router.post("/login")
async def login(
    body: LoginRequest,
    response: Response,
    service: Annotated[AuthService, Depends(get_auth_service)],
    login_marker: Annotated[Literal["1"], Header(alias="X-Ops-Login")],
) -> SessionResponse:
    try:
        issued = await service.login(body.username, body.password.get_secret_value())
    except LoginRejected as error:
        raise HTTPException(
            429 if error.locked else 401,
            str(error),
            headers={"Retry-After": str(service.config.login_lock_seconds)}
            if error.locked
            else None,
        ) from None
    except (SQLAlchemyError, OSError, TimeoutError):
        raise HTTPException(503, "会话存储暂时不可用") from None
    response.set_cookie(
        service.config.cookie_name,
        issued.cookie,
        max_age=service.config.session_ttl_seconds,
        httponly=True,
        secure=service.config.secure_cookie,
        samesite="strict",
        path="/",
    )
    return session_response(issued.principal)


@router.get("/me")
async def me(principal: CurrentPrincipal) -> SessionResponse:
    return session_response(principal)


@router.post("/logout", status_code=204)
async def logout(
    principal: CurrentPrincipal,
    service: Annotated[AuthService, Depends(get_auth_service)],
    csrf_token: Annotated[str, Header(alias="X-CSRF-Token")],
) -> Response:
    try:
        await service.logout(principal)
    except (SQLAlchemyError, OSError, TimeoutError):
        raise HTTPException(503, "会话存储暂时不可用") from None
    response = Response(status_code=204)
    response.delete_cookie(
        service.config.cookie_name,
        path="/",
        secure=service.config.secure_cookie,
        httponly=True,
        samesite="strict",
    )
    return response

"""任务闭环 HTTP 适配；查询和操作均由业务服务完成。"""

from typing import Annotated
from uuid import UUID

from fastapi import APIRouter, Depends, Header, HTTPException, Query, Request
from sqlalchemy.ext.asyncio import AsyncSession
from temporalio.client import Client, WorkflowFailureError
from temporalio.service import RPCError

from app.api.auth import CurrentPrincipal
from app.api.dependencies import get_session
from app.config import Settings
from app.db.session import Database
from app.learning.models import IncidentHit
from app.ledger.models import Evidence
from app.tasks.console_models import (
    AnswerInput,
    ApprovalInput,
    ControlCommand,
    ControlReceipt,
    EventView,
    EvidenceView,
    HistoryView,
    InteractionView,
    Page,
    TakeoverInput,
    TaskView,
    ToolCallView,
)
from app.tasks.console_queries import ConsoleQueries
from app.tasks.control import ControlGateway
from app.tasks.models import TaskStatusHistory
from app.tasks.states import TaskSource, TaskStatus
from app.tools.registry import json_object
from app.triggers.schemas import EventOrigin

router = APIRouter(
    prefix="/api",
    tags=["任务闭环"],
    responses={
        401: {"description": "请先登录"},
        404: {"description": "记录不存在"},
        409: {"description": "等待版本或操作内容冲突"},
        503: {"description": "本地存储或 Temporal 暂时不可用"},
    },
)
Limit = Annotated[int, Query(ge=1, le=100)]
Offset = Annotated[int, Query(ge=0)]
ServiceName = Annotated[str | None, Query(min_length=1, max_length=256)]
Csrf = Annotated[str, Header(alias="X-CSRF-Token")]


def get_queries(session: Annotated[AsyncSession, Depends(get_session)]) -> ConsoleQueries:
    return ConsoleQueries(session)


Queries = Annotated[ConsoleQueries, Depends(get_queries)]


async def get_control_gateway(request: Request) -> ControlGateway:
    settings: Settings = request.app.state.settings
    database: Database | None = getattr(request.app.state, "database", None)
    if database is None:
        raise HTTPException(503, "任务操作需要 DATABASE_URL")
    from app.tasks.worker import validate_placeholder_settings

    try:
        validate_placeholder_settings(settings)
        client = await Client.connect(
            settings.temporal_config.address, namespace=settings.temporal_config.namespace
        )
    except (ValueError, RuntimeError, RPCError, OSError, TimeoutError):
        raise HTTPException(503, "Temporal 任务操作暂时不可用") from None
    return ControlGateway(client, settings, database)


Gateway = Annotated[ControlGateway, Depends(get_control_gateway)]


