"""本包的固定 GET 传输与严格解析；不跟随响应中的 URL，不自建重试。"""

from datetime import datetime

import httpx2 as httpx
from pydantic import JsonValue, TypeAdapter

from app.connectors.changes.base import (
    ChangesError,
    ChangesHTTPError,
    ChangesNotFound,
    ChangesResponseError,
    ChangesTimeout,
)
from app.connectors.changes.config import EndpointConfig
from app.connectors.models import ReaderCredentials


def obj(value: JsonValue) -> dict[str, JsonValue]:
    if not isinstance(value, dict):
        raise ChangesResponseError("变更链路响应必须是对象")
    return value


def rows(value: JsonValue) -> list[dict[str, JsonValue]]:
    if not isinstance(value, list):
        raise ChangesResponseError("变更链路响应必须是列表")
    return [obj(item) for item in value]


def string(value: JsonValue) -> str:
    if not isinstance(value, str) or not value:
        raise ChangesResponseError("变更链路字段必须是非空字符串")
    return value


def integer(value: JsonValue) -> int:
    if type(value) is not int:
        raise ChangesResponseError("变更链路字段必须是整数")
    return value


def instant(value: JsonValue) -> datetime:
    try:
        result = datetime.fromisoformat(string(value))
        if result.utcoffset() is None:
            raise ValueError
        return result
    except ValueError:
        raise ChangesResponseError("变更链路时间必须包含时区") from None


def unique(values: list[str]) -> None:
    if len(set(values)) != len(values):
        raise ChangesResponseError("变更链路响应含重复记录")


class ReaderHTTP:
    def __init__(
        self,
        config: EndpointConfig,
        credentials: ReaderCredentials,
        name: str,
        transport: httpx.MockTransport | None,
        *,
        username: str | None = None,
    ) -> None:
        if credentials.connector != name:
            raise ValueError(f"只接受 {name} 的 Reader 凭证")
        token = credentials.token.get_secret_value()
        if any(char.isspace() or ord(char) < 32 for char in token):
            raise ValueError("变更链路 Reader token 不能包含空白或控制字符")
        if transport is not None and not isinstance(transport, httpx.MockTransport):
            raise TypeError("测试 transport 只接受 MockTransport")
        self.config = EndpointConfig.model_validate(
            {key: getattr(config, key) for key in EndpointConfig.model_fields}
        )
        headers = {"Accept": "application/json"}
        auth: httpx.BasicAuth | None = None
        if name == "ci" and username is not None:
            auth = httpx.BasicAuth(username, token)
        elif name in {"git", "ci"} and getattr(config, "provider", None) in {"gitlab", "gitlab_ci"}:
            headers["PRIVATE-TOKEN"] = token
        else:
            headers["Authorization"] = f"Bearer {token}"
        if name == "git" and getattr(config, "provider", None) == "github":
            headers["Accept"] = "application/vnd.github+json"
            headers["X-GitHub-Api-Version"] = "2022-11-28"
        self.client = httpx.AsyncClient(
            base_url=self.config.base_url,
            headers=headers,
            auth=auth,
            timeout=self.config.timeout_seconds,
            transport=transport,
            trust_env=False,
            follow_redirects=False,
        )

    def target(self, service: str) -> str:
        target = self.config.services.get(service)
        if target is None:
            raise ChangesNotFound("服务没有配置变更来源绑定")
        return target

    async def read(self, path: str, params: dict[str, str] | None = None) -> httpx.Response:
        if self.client.is_closed:
            raise ChangesError("变更链路 Connector 已关闭")
        try:
            response = await self.client.get(path, params=params)
        except httpx.TimeoutException:
            raise ChangesTimeout("变更链路读取超时") from None
        except httpx.RequestError:
            raise ChangesError("变更链路连接失败") from None
        if response.status_code == 404:
            raise ChangesNotFound("变更链路记录不存在")
        if response.status_code != 200:
            raise ChangesHTTPError(response.status_code)
        return response


def payload(response: httpx.Response) -> JsonValue:
    try:
        return TypeAdapter(JsonValue).validate_json(response.content)
    except ValueError:
        raise ChangesResponseError("变更链路响应不是有效 JSON") from None

"""按需读取的代码、构建、发布和配置差异快照。"""

from datetime import UTC, datetime, timedelta
from typing import Annotated, Literal

from pydantic import AwareDatetime, BaseModel, ConfigDict, Field, field_validator, model_validator

ServiceName = Annotated[str, Field(pattern=r"^[A-Za-z0-9][A-Za-z0-9_.-]{0,127}$")]
Reference = Annotated[str, Field(pattern=r"^[A-Za-z0-9][A-Za-z0-9_./-]{0,255}$")]
Identifier = Annotated[str, Field(min_length=1, max_length=512)]


def non_secret_config_keys(keys: tuple[str, ...]) -> tuple[str, ...]:
    for key in keys:
        normalized = key.lower().replace("_", "").replace(".", "").replace("-", "")
        if not key or any(
            part in normalized
            for part in (
                "password",
                "passwd",
                "secret",
                "token",
                "credential",
                "privatekey",
                "accesskey",
                "apikey",
            )
        ):
            raise ValueError("配置快照和白名单不能包含凭证或密钥字段")
    return keys


class Snapshot(BaseModel):
    model_config = ConfigDict(
        strict=True,
        frozen=True,
        extra="forbid",
        revalidate_instances="always",
        hide_input_in_errors=True,
    )


class VersionQuery(Snapshot):
    service_name: ServiceName
    from_version: Reference
    to_version: Reference

    @field_validator("from_version", "to_version")
    @classmethod
    def safe_ref(cls, value: str) -> str:
        if any(part in {"", ".", ".."} for part in value.split("/")) or ".." in value:
            raise ValueError("版本引用不能包含空段或路径跳转")
        return value


class DeploymentQuery(Snapshot):
    service_name: ServiceName
    start: AwareDatetime
    end: AwareDatetime

    @field_validator("start", "end")
    @classmethod
    def utc(cls, value: datetime) -> datetime:
        return value.astimezone(UTC)

    @model_validator(mode="after")
    def ordered(self) -> "DeploymentQuery":
        if not timedelta(0) < self.end - self.start <= timedelta(days=30):
            raise ValueError("时间窗必须 start < end 且不超过 30 天")
        return self

    def contains(self, value: datetime) -> bool:
        return self.start <= value < self.end


class FileDiff(Snapshot):
    old_path: Identifier
    new_path: Identifier
    patch: str = Field(max_length=1_000_000)
    status: Literal["added", "modified", "removed", "renamed"]
    content_available: bool = True


class CodeComparison(VersionQuery):
    source: Literal["gitlab", "github"]
    repository: Identifier
    files: tuple[FileDiff, ...]
    # GitHub 是 merge-base 比较；明确保留语义，避免误当成直接配置差异。
    comparison_kind: Literal["direct", "merge_base"]
    source_ref: Identifier


class Repository(Snapshot):
    service_name: ServiceName
    source: Literal["gitlab", "github"]
    repository_id: Identifier
    name: Identifier
    source_ref: Identifier


class ConfigChange(Snapshot):
    key: Identifier
    before: str | None
    after: str | None


class ConfigComparison(VersionQuery):
    source: Literal["config_center"] = "config_center"
    changes: tuple[ConfigChange, ...]
    source_ref: Identifier


class TimedRecord(Snapshot):
    id: Identifier
    service_name: ServiceName
    timestamp: AwareDatetime
    source_ref: Identifier

    @field_validator("timestamp")
    @classmethod
    def utc(cls, value: datetime) -> datetime:
        return value.astimezone(UTC)


class BuildRecord(TimedRecord):
    source: Literal["jenkins", "gitlab_ci"]
    revision: Identifier | None
    status: Identifier


class DeploymentRecord(TimedRecord):
    source: Literal["argocd"] = "argocd"
    application: Identifier
    revision: Identifier


class ChangeRecord(TimedRecord):
    """历史变更只携带引用，不携带日志、配置值、凭证或提交正文。"""

    source: Literal["gitlab", "github", "config_center"]
    kind: Literal["Commit", "Merge", "Config"]
    revision: Identifier | None = None

    @model_validator(mode="after")
    def source_kind(self) -> "ChangeRecord":
        if (self.source == "config_center") != (self.kind == "Config"):
            raise ValueError("变更类型与源系统不符")
        return self


class ConfigVersion(Snapshot):
    service_name: ServiceName
    version: Reference
    # 只允许非敏感白名单配置；凭证和密钥不能进入快照。
    values: dict[str, str]

    @field_validator("values")
    @classmethod
    def non_secret_values(cls, value: dict[str, str]) -> dict[str, str]:
        non_secret_config_keys(tuple(value))
        return value


def config_diff(before: ConfigVersion, after: ConfigVersion) -> ConfigComparison:
    if before.service_name != after.service_name:
        raise ValueError("配置版本必须属于同一个服务")
    changes = tuple(
        ConfigChange(key=key, before=before.values.get(key), after=after.values.get(key))
        for key in sorted(before.values.keys() | after.values.keys())
        if before.values.get(key) != after.values.get(key)
    )
    return ConfigComparison(
        service_name=before.service_name,
        from_version=before.version,
        to_version=after.version,
        changes=changes,
        source_ref=f"config_center:{before.service_name}:{before.version}..{after.version}",
    )

