class FakeCloudConnector(CloudConnector):
    def __init__(
        self,
        *,
        resources: tuple[CloudResource, ...] | None = None,
        events: tuple[CloudEvent, ...] | None = None,
        topics: tuple[CloudTopic, ...] | None = None,
    ) -> None:
        super().__init__()
        self._resources = tuple(
            CloudResource.model_validate(r.model_dump())
            for r in (sample_resources() if resources is None else resources)
        )
        self._events = tuple(
            CloudEvent.model_validate(e.model_dump())
            for e in (sample_events() if events is None else events)
        )
        if len({(r.service_name, *r.identity) for r in self._resources}) != len(self._resources):
            raise ValueError("Fake 云资源不能重复")
        if len({e.id for e in self._events}) != len(self._events):
            raise ValueError("Fake 云事件不能重复")
        for event in self._events:
            if not any(
                (r.service_name, *r.identity)
                == (event.service_name, event.product, event.region_id, event.resource_id)
                for r in self._resources
            ):
                raise ValueError("Fake 云事件必须关联已有资源")
        self._closed = False
        self._topics = (
            topics
            if topics is not None
            else (
                CloudTopic(
                    region_id="cn-hangzhou", instance_id="MQ_INST_payment", name="payment-events"
                ),
            )
        )

    async def aclose(self) -> None:
        self._closed = True

    async def list_topics(self, service_name: str) -> tuple[CloudTopic, ...]:
        if self._closed:
            raise CloudError("阿里云 Connector 已关闭")
        query = CloudQuery(service_name=service_name)
        targets = {
            (r.region_id, r.resource_id)
            for r in self._resources
            if r.product == "mq" and r.service_name == query.service_name
        }
        return tuple(
            CloudTopic.model_validate(t).model_copy(deep=True)
            for t in self._topics
            if (t.region_id, t.instance_id) in targets
        )

    async def get_cloud_resources(self, query: CloudQuery) -> CloudResources:
        if self._closed:
            raise CloudError("阿里云 Connector 已关闭")
        query = CloudQuery.model_validate(query.model_dump())
        window = query.resolve(SAMPLE_END)
        resources: list[CloudResource] = []
        for resource in self._resources:
            if resource.service_name != query.service_name:
                continue
            copy = CloudResource.model_validate(resource.model_dump())
            sample = copy.rds_connections
            if (
                sample is not None
                and sample.sampled_at is not None
                and not window.contains(sample.sampled_at)
            ):
                copy = CloudResource.model_validate(
                    {
                        **copy.model_dump(),
                        "rds_connections": RDSConnections(
                            availability="no_data", max_connections=sample.max_connections
                        ),
                    }
                )
            resources.append(copy)
        if not resources:
            raise CloudNotFound("服务没有 Fake 阿里云资源")
        return CloudResources(
            **window.model_dump(),
            collected_at=SAMPLE_END,
            resources=tuple(sorted(resources, key=lambda resource: resource.identity)),
            events=tuple(
                sorted(
                    (
                        CloudEvent.model_validate(e.model_dump())
                        for e in self._events
                        if e.service_name == query.service_name and window.contains(e.timestamp)
                    ),
                    key=lambda event: (event.timestamp, event.id),
                    reverse=True,
                )
            ),
        )

"""按服务读取的最小云资源状态；不保存原始云响应或指标序列。"""

from datetime import UTC, datetime, timedelta
from typing import Annotated, Literal

from pydantic import AwareDatetime, BaseModel, ConfigDict, Field, field_validator, model_validator

Product = Literal["ecs", "rds", "redis", "mq", "slb", "vpc", "dns", "cdn"]
APIProduct = Literal["ecs", "rds", "redis", "mq", "slb", "vpc", "dns", "cdn", "cms"]
ServiceName = Annotated[str, Field(pattern=r"^[A-Za-z0-9][A-Za-z0-9_.-]{0,127}$")]
ResourceID = Annotated[str, Field(pattern=r"^[A-Za-z0-9][A-Za-z0-9_.-]{0,255}$")]
RegionID = Annotated[str, Field(pattern=r"^[a-z0-9][a-z0-9-]{0,63}$")]
Text = Annotated[str, Field(min_length=1, max_length=512)]


class Snapshot(BaseModel):
    model_config = ConfigDict(
        strict=True,
        frozen=True,
        extra="forbid",
        revalidate_instances="always",
        hide_input_in_errors=True,
    )


class CloudQuery(Snapshot):
    service_name: ServiceName
    start: AwareDatetime | None = None
    end: AwareDatetime | None = None

    @field_validator("start", "end")
    @classmethod
    def utc(cls, value: datetime | None) -> datetime | None:
        return value.astimezone(UTC) if value is not None else None

    @model_validator(mode="after")
    def window(self) -> "CloudQuery":
        if (self.start is None) != (self.end is None):
            raise ValueError("start 与 end 必须同时提供或同时省略")
        if self.start is not None and self.end is not None:
            if not timedelta(0) < self.end - self.start <= timedelta(days=1):
                raise ValueError("UTC 时间窗必须 start < end 且不超过 24 小时")
        return self

    def resolve(self, now: datetime) -> "CloudWindow":
        return CloudWindow(
            service_name=self.service_name,
            start=self.start if self.start is not None else now - timedelta(minutes=15),
            end=self.end if self.end is not None else now,
        )


class CloudWindow(CloudQuery):
    start: AwareDatetime
    end: AwareDatetime

    def contains(self, value: datetime) -> bool:
        return self.start <= value < self.end


class ResourceDetails(Snapshot):
    engine: Text | None = None
    engine_version: Text | None = None
    instance_type: Text | None = None
    vpc_id: ResourceID | None = None
    zone_id: Text | None = None
    cname: Text | None = None
    in_black_hole: bool | None = None
    in_clean: bool | None = None


class RDSConnections(Snapshot):
    availability: Literal["available", "no_data", "unsupported_engine"]
    max_connections: int | None = Field(default=None, ge=0)
    sampled_at: AwareDatetime | None = None
    active_connections: float | None = Field(default=None, ge=0, allow_inf_nan=False)
    total_connections: float | None = Field(default=None, ge=0, allow_inf_nan=False)
    metric_key: Literal["MySQL_Sessions"] | None = "MySQL_Sessions"

    @field_validator("sampled_at")
    @classmethod
    def utc(cls, value: datetime | None) -> datetime | None:
        return value.astimezone(UTC) if value is not None else None

    @model_validator(mode="after")
    def values(self) -> "RDSConnections":
        if (self.availability == "unsupported_engine") != (self.metric_key is None):
            raise ValueError("不支持的引擎不能声称查询了 MySQL 指标")
        sample = (self.sampled_at, self.active_connections, self.total_connections)
        if self.availability == "available":
            if any(value is None for value in sample):
                raise ValueError("可用的连接数必须含采样时间、活跃和总连接数")
            assert self.active_connections is not None and self.total_connections is not None
            if self.active_connections > self.total_connections:
                raise ValueError("活跃连接数不能大于总连接数")
        elif any(value is not None for value in sample):
            raise ValueError("缺失的连接数不能伪造为零或携带采样值")
        return self


class CloudResource(Snapshot):
    service_name: ServiceName
    product: Product
    resource_id: ResourceID
    region_id: RegionID
    status: Text | None
    source_ref: Text
    details: ResourceDetails = Field(default_factory=ResourceDetails)
    rds_connections: RDSConnections | None = None

    @model_validator(mode="after")
    def connections(self) -> "CloudResource":
        if (self.product == "rds") != (self.rds_connections is not None):
            raise ValueError("只有 RDS 资源且所有 RDS 资源须声明连接数观测状态")
        return self

    @property
    def identity(self) -> tuple[str, str, str]:
        return self.product, self.region_id, self.resource_id


class CloudEvent(Snapshot):
    id: Text
    service_name: ServiceName
    product: Product
    resource_id: ResourceID
    region_id: RegionID
    timestamp: AwareDatetime
    name: Text
    level: Literal["CRITICAL", "WARN", "INFO"]
    status: Text
    source_ref: Text

    @field_validator("timestamp")
    @classmethod
    def utc(cls, value: datetime) -> datetime:
        return value.astimezone(UTC)


class CloudTopic(Snapshot):
    region_id: RegionID
    instance_id: ResourceID
    name: ResourceID


class CloudResources(CloudWindow):
    source: Literal["alibaba_cloud"] = "alibaba_cloud"
    scope: Literal["configured_service_bindings"] = "configured_service_bindings"
    collected_at: AwareDatetime
    resources: tuple[CloudResource, ...]
    events: tuple[CloudEvent, ...]

    @field_validator("collected_at")
    @classmethod
    def collected_utc(cls, value: datetime) -> datetime:
        return value.astimezone(UTC)

    @model_validator(mode="after")
    def scoped(self) -> "CloudResources":
        identities = {resource.identity for resource in self.resources}
        if len(identities) != len(self.resources):
            raise ValueError("云资源不能重复")
        if any(resource.service_name != self.service_name for resource in self.resources):
            raise ValueError("云资源必须属于查询服务")
        for resource in self.resources:
            sample = resource.rds_connections
            if sample is not None and sample.sampled_at is not None:
                if not self.contains(sample.sampled_at):
                    raise ValueError("RDS 采样必须在查询时间窗内")
        if len({event.id for event in self.events}) != len(self.events):
            raise ValueError("云事件不能重复")
        for event in self.events:
            if (
                event.service_name != self.service_name
                or not self.contains(event.timestamp)
                or (event.product, event.region_id, event.resource_id) not in identities
            ):
                raise ValueError("云事件超出服务、资源或时间范围")
        return self

"""按宿主配置选择已注册的只读适配器；不导入或自动发现外部 SDK。"""

import re
from collections.abc import Callable

from app.config import Settings
from app.connectors.base import ReadOnlyConnector, WriteConnector
from app.connectors.models import ConnectorMode, ReaderCredentials


class ConnectorFactory[Reader: ReadOnlyConnector]:
    def __init__(
        self,
        name: str,
        *,
        fake: Callable[[], Reader],
        real: Callable[[ReaderCredentials], Reader],
    ) -> None:
        if re.fullmatch(r"[a-z][a-z0-9_]{0,63}", name) is None:
            raise ValueError("Connector 名称必须是最多 64 字符的英文标识符")
        self._name = name
        self._fake = fake
        self._real = real

    def create(self, settings: Settings) -> Reader:
        # 重新验证宿主配置，防止赋值或 model_copy 绕过 local/test 门禁。
        config = Settings.model_validate(
            {
                field.validation_alias
                if isinstance(field.validation_alias, str)
                else name: getattr(settings, name)
                for name, field in Settings.model_fields.items()
            }
        )
        if config.connector_mode is ConnectorMode.FAKE:
            reader = self._fake()
            if (
                not isinstance(reader, ReadOnlyConnector)
                or isinstance(reader, WriteConnector)
                or reader.reader_credentials is not None
            ):
                raise TypeError("Fake 工厂必须返回不携带真实凭证的只读 Connector")
            return reader
        token = config.connector_reader_tokens.get(self._name)
        if token is None:
            raise ValueError(f"请在 CONNECTOR_READER_TOKENS 中设置 {self._name} 的只读凭证")
        credentials = ReaderCredentials(connector=self._name, token=token)
        reader = self._real(credentials)
        if (
            not isinstance(reader, ReadOnlyConnector)
            or isinstance(reader, WriteConnector)
            or reader.reader_credentials != credentials
        ):
            raise TypeError("真实工厂必须返回绑定该 Reader 凭证的只读 Connector")
        return reader

"""平台通知接口：不属于 Agent Tool 或生产动作 Executor。"""

from abc import abstractmethod
from uuid import UUID

from app.connectors.base import Connector
from app.connectors.feishu.models import (
    CardNotification,
    InteractiveCard,
    Notification,
    NotificationReceipt,
    TextNotification,
)


class FeishuError(RuntimeError):
    """飞书异常只保留安全错误类别，不携带消息、凭证或源系统响应。"""


class FeishuHTTPError(FeishuError):
    def __init__(self, status_code: int) -> None:
        self.status_code = status_code
        super().__init__(f"飞书通知返回 HTTP {status_code}")


class FeishuAPIError(FeishuError):
    def __init__(self, code: int) -> None:
        self.code = code
        super().__init__(f"飞书通知返回业务错误码 {code}")


class FeishuResponseError(FeishuError):
    pass


class FeishuTimeout(FeishuError):
    pass


class FeishuTransportError(FeishuError):
    pass


class FeishuConnector(Connector):
    @abstractmethod
    async def send(self, notification: Notification) -> NotificationReceipt: ...

    async def send_text(
        self, text: str, *, notification_id: UUID | None = None
    ) -> NotificationReceipt:
        notification = (
            TextNotification(text=text)
            if notification_id is None
            else TextNotification(text=text, notification_id=notification_id)
        )
        return await self.send(notification)

    async def send_card(
        self, card: InteractiveCard, *, notification_id: UUID | None = None
    ) -> NotificationReceipt:
        notification = (
            CardNotification(card=card)
            if notification_id is None
            else CardNotification(card=card, notification_id=notification_id)
        )
        return await self.send(notification)

"""飞书自建应用 HTTP 通知适配器；仅获取短时 token 与向本人发送消息。"""

from datetime import UTC, datetime

import httpx2 as httpx
from pydantic import BaseModel, ConfigDict, Field, SecretStr, ValidationError, field_validator

from app.connectors.feishu.base import (
    FeishuAPIError,
    FeishuConnector,
    FeishuError,
    FeishuHTTPError,
    FeishuResponseError,
    FeishuTimeout,
    FeishuTransportError,
)
from app.connectors.feishu.config import FeishuConfig, FeishuNotificationCredentials
from app.connectors.feishu.models import (
    Notification,
    NotificationReceipt,
    checked_notification,
    notification_content,
)


class _Envelope(BaseModel):
    model_config = ConfigDict(strict=True, hide_input_in_errors=True)
    code: int


class _TokenResponse(_Envelope):
    tenant_access_token: SecretStr
    expire: int = Field(gt=0)

    @field_validator("tenant_access_token")
    @classmethod
    def validate_token(cls, value: SecretStr) -> SecretStr:
        token = value.get_secret_value()
        if not token or any(char.isspace() or ord(char) < 32 for char in token):
            raise ValueError("飞书 token 无效")
        return value


class _MessageData(BaseModel):
    model_config = ConfigDict(strict=True, hide_input_in_errors=True)
    message_id: str = Field(pattern=r"^om_[A-Za-z0-9_-]{1,128}$")


class _MessageResponse(_Envelope):
    data: _MessageData


class HTTPFeishuConnector(FeishuConnector):
    def __init__(
        self,
        config: FeishuConfig,
        credentials: FeishuNotificationCredentials,
        *,
        transport: httpx.MockTransport | None = None,
    ) -> None:
        if not isinstance(credentials, FeishuNotificationCredentials):
            raise TypeError("飞书通知只接受独立的 FeishuNotificationCredentials")
        self._config = FeishuConfig.model_validate(config)
        self._credentials = FeishuNotificationCredentials.model_validate(credentials)
        if transport is not None and not isinstance(transport, httpx.MockTransport):
            raise TypeError("测试 transport 只接受 MockTransport")
        self._http = httpx.AsyncClient(
            base_url="https://open.feishu.cn/open-apis/",
            headers={"Accept": "application/json"},
            timeout=self._config.timeout_seconds,
            transport=transport,
            trust_env=False,
            follow_redirects=False,
        )

    async def aclose(self) -> None:
        await self._http.aclose()

    async def _post(
        self,
        path: str,
        body: dict[str, str],
        *,
        token: SecretStr | None = None,
        params: dict[str, str] | None = None,
    ) -> bytes:
        if self._http.is_closed:
            raise FeishuError("飞书通知 Connector 已关闭")
        headers = {"Authorization": f"Bearer {token.get_secret_value()}"} if token else {}
        try:
            response = await self._http.post(path, json=body, headers=headers, params=params)
        except httpx.TimeoutException:
            raise FeishuTimeout("飞书通知请求超时；发送结果可能未知") from None
        except httpx.RequestError:
            raise FeishuTransportError("飞书通知连接失败；发送结果可能未知") from None
        if not response.is_success:
            raise FeishuHTTPError(response.status_code)
        try:
            envelope = _Envelope.model_validate_json(response.content)
        except ValidationError:
            raise FeishuResponseError("飞书通知响应格式无效") from None
        if envelope.code != 0:
            raise FeishuAPIError(envelope.code)
        return response.content

    async def send(self, notification: Notification) -> NotificationReceipt:
        if self._http.is_closed:
            raise FeishuError("飞书通知 Connector 已关闭")
        snapshot = checked_notification(notification)
        content = notification_content(snapshot)
        # 不建立自己的续期循环或重试调度；token 仅在当前发送中使用。
        token_body = await self._post(
            "auth/v3/tenant_access_token/internal",
            {
                "app_id": self._credentials.app_id,
                "app_secret": self._credentials.app_secret.get_secret_value(),
            },
        )
        try:
            token = _TokenResponse.model_validate_json(token_body).tenant_access_token
        except ValidationError:
            raise FeishuResponseError("飞书短时 token 响应格式无效") from None
        result = await self._post(
            "im/v1/messages",
            {
                "receive_id": self._config.recipient_open_id,
                "msg_type": snapshot.msg_type,
                "content": content,
                "uuid": str(snapshot.notification_id),
            },
            token=token,
            params={"receive_id_type": "open_id"},
        )
        try:
            message = _MessageResponse.model_validate_json(result)
        except ValidationError:
            raise FeishuResponseError("飞书发送确认格式无效；发送结果可能未知") from None
        return NotificationReceipt(
            notification_id=snapshot.notification_id,
            message_id=message.data.message_id,
            accepted_at=datetime.now(UTC),
        )

"""飞书自建应用的通知配置与独立凭证；只由环境变量注入。"""

from pydantic import BaseModel, ConfigDict, Field, SecretStr, field_validator


class FeishuConfig(BaseModel):
    model_config = ConfigDict(
        frozen=True, extra="forbid", revalidate_instances="always", hide_input_in_errors=True
    )

    # 绑定本人 open_id，发送接口不接受任意收件人或群聊。
    recipient_open_id: str = Field(pattern=r"^ou_[A-Za-z0-9_-]{1,128}$")
    timeout_seconds: float = Field(default=15, gt=0, le=120, allow_inf_nan=False)


class FeishuNotificationCredentials(BaseModel):
    """通知身份不能作为 AI Reader 或 AI Executor 使用。"""

    model_config = ConfigDict(
        frozen=True, extra="forbid", revalidate_instances="always", hide_input_in_errors=True
    )

    app_id: str = Field(pattern=r"^cli_[A-Za-z0-9_-]{1,128}$")
    app_secret: SecretStr

    @field_validator("app_secret")
    @classmethod
    def validate_secret(cls, value: SecretStr) -> SecretStr:
        secret = value.get_secret_value()
        if not secret or any(char.isspace() or ord(char) < 32 for char in secret):
            raise ValueError("飞书通知 app_secret 不能为空或含空白、控制字符")
        return value

"""按 CONNECTOR_MODE 选择通知通道；不使用只读工厂或生产动作凭证。"""

import httpx2 as httpx

from app.config import Settings
from app.connectors.feishu.base import FeishuConnector
from app.connectors.feishu.client import HTTPFeishuConnector
from app.connectors.feishu.fake import FakeFeishuConnector
from app.connectors.models import ConnectorMode


def create_feishu_connector(
    settings: Settings, *, transport: httpx.MockTransport | None = None
) -> FeishuConnector:
    config = Settings.model_validate(
        {
            field.validation_alias if isinstance(field.validation_alias, str) else name: getattr(
                settings, name
            )
            for name, field in Settings.model_fields.items()
        }
    )
    if config.connector_mode is ConnectorMode.FAKE:
        # Fake 不读取真实通知凭证，也不构建 HTTP 客户端。
        return FakeFeishuConnector()
    if config.feishu_notification_credentials is None:
        raise ValueError("请通过环境变量设置 FEISHU_NOTIFICATION_CREDENTIALS")
    return HTTPFeishuConnector(
        config.require_feishu_config(), config.feishu_notification_credentials, transport=transport
    )

"""内存 Fake 发件箱：完整读回内容、固定本人收件人、同 ID 重发去重。"""

from datetime import UTC, datetime
from uuid import UUID

from app.connectors.feishu.base import FeishuConnector, FeishuError
from app.connectors.feishu.config import FeishuConfig
from app.connectors.feishu.models import (
    Notification,
    NotificationReceipt,
    SentNotification,
    checked_notification,
    notification_content,
)


class FakeFeishuConnector(FeishuConnector):
    def __init__(self, *, recipient_open_id: str = "ou_fake_owner") -> None:
        self._recipient = FeishuConfig(recipient_open_id=recipient_open_id).recipient_open_id
        self._sent: dict[UUID, SentNotification] = {}
        self._closed = False

    @property
    def sent_messages(self) -> tuple[SentNotification, ...]:
        return tuple(record.model_copy(deep=True) for record in self._sent.values())

    def get_sent(self, notification_id: UUID) -> SentNotification:
        return self._sent[notification_id].model_copy(deep=True)

    async def send(self, notification: Notification) -> NotificationReceipt:
        if self._closed:
            raise FeishuError("Fake 飞书通知 Connector 已关闭")
        snapshot = checked_notification(notification)
        notification_content(snapshot)
        previous = self._sent.get(snapshot.notification_id)
        if previous is not None:
            if previous.notification != snapshot:
                raise FeishuError("同一 notification_id 不能发送不同内容")
            return previous.receipt.model_copy(deep=True)
        receipt = NotificationReceipt(
            notification_id=snapshot.notification_id,
            message_id=f"fake_{snapshot.notification_id}",
            accepted_at=datetime.now(UTC),
        )
        self._sent[snapshot.notification_id] = SentNotification(
            recipient_open_id=self._recipient, notification=snapshot, receipt=receipt
        )
        return receipt.model_copy(deep=True)

    async def aclose(self) -> None:
        self._closed = True

"""有限的文本/交互卡片协议；按钮只携带回调数据，不执行审批或运维动作。"""

import json
from datetime import UTC, datetime
from typing import Annotated, Literal
from uuid import UUID, uuid4

from pydantic import BaseModel, ConfigDict, Field, JsonValue, TypeAdapter, field_validator


class NotificationModel(BaseModel):
    model_config = ConfigDict(
        frozen=True,
        extra="forbid",
        strict=True,
        revalidate_instances="always",
        hide_input_in_errors=True,
    )


class CardButton(NotificationModel):
    label: str = Field(min_length=1, max_length=100)
    value: dict[str, JsonValue] = Field(min_length=1)
    style: Literal["default", "primary", "danger"] = "default"

    @field_validator("label")
    @classmethod
    def validate_label(cls, value: str) -> str:
        if not value.strip():
            raise ValueError("卡片按钮文字不能为空")
        return value


class InteractiveCard(NotificationModel):
    title: str = Field(min_length=1, max_length=128)
    markdown: str = Field(min_length=1, max_length=4096)
    buttons: tuple[CardButton, ...] = Field(min_length=1, max_length=5)

    @field_validator("title", "markdown")
    @classmethod
    def validate_text(cls, value: str) -> str:
        if not value.strip():
            raise ValueError("卡片标题与内容不能为空")
        return value


class TextNotification(NotificationModel):
    msg_type: Literal["text"] = "text"
    notification_id: UUID = Field(default_factory=uuid4)
    text: str = Field(min_length=1, max_length=4096)

    @field_validator("text")
    @classmethod
    def validate_text(cls, value: str) -> str:
        if not value.strip():
            raise ValueError("通知文本不能为空")
        return value


class CardNotification(NotificationModel):
    msg_type: Literal["interactive"] = "interactive"
    notification_id: UUID = Field(default_factory=uuid4)
    card: InteractiveCard


Notification = Annotated[TextNotification | CardNotification, Field(discriminator="msg_type")]
_notification: TypeAdapter[TextNotification | CardNotification] = TypeAdapter(Notification)


def checked_notification(value: Notification) -> Notification:
    # 不信任 model_copy；深复制嵌套按钮数据，发送与 Fake 快照不会共享可变字典。
    return _notification.validate_python(value).model_copy(deep=True)


def notification_content(notification: Notification) -> str:
    if isinstance(notification, TextNotification):
        content: dict[str, JsonValue] = {"text": notification.text}
    else:
        card = notification.card
        content = {
            "config": {"wide_screen_mode": True},
            "header": {"title": {"tag": "plain_text", "content": card.title}},
            "elements": [
                {"tag": "div", "text": {"tag": "lark_md", "content": card.markdown}},
                {
                    "tag": "action",
                    "actions": [
                        {
                            "tag": "button",
                            "text": {"tag": "plain_text", "content": button.label},
                            "type": button.style,
                            "value": button.value,
                        }
                        for button in card.buttons
                    ],
                },
            ],
        }
    try:
        encoded = json.dumps(content, ensure_ascii=False, allow_nan=False, separators=(",", ":"))
        size = len(encoded.encode("utf-8"))
    except (ValueError, TypeError, UnicodeError):
        raise ValueError("通知内容必须为有效 UTF-8 JSON，且不含非有限数值") from None
    # 本平台主动使用更小的上限，包含按钮回调数据。
    if size > 20 * 1024:
        raise ValueError("通知内容超过本平台 20 KiB 上限")
    return encoded


class NotificationReceipt(NotificationModel):
    notification_id: UUID
    message_id: str = Field(min_length=1, max_length=200)
    accepted_at: datetime

    @field_validator("accepted_at")
    @classmethod
    def validate_time(cls, value: datetime) -> datetime:
        if value.tzinfo is None or value.utcoffset() is None:
            raise ValueError("通知接收确认时间必须带时区")
        return value.astimezone(UTC)


class SentNotification(NotificationModel):
    recipient_open_id: str
    notification: Notification
    receipt: NotificationReceipt

