import json
from abc import abstractmethod

import httpx2 as httpx

from app.connectors.base import ReadOnlyConnector
from app.connectors.holmes.models import HolmesConfig, HolmesRequest, HolmesResponse
from app.connectors.models import ReaderCredentials


class HolmesError(RuntimeError):
    pass


class HolmesConnector(ReadOnlyConnector):
    @abstractmethod
    async def analyze(self, request: HolmesRequest) -> HolmesResponse: ...


class HTTPHolmesConnector(HolmesConnector):
    def __init__(
        self,
        config: HolmesConfig,
        credentials: ReaderCredentials,
        *,
        transport: httpx.MockTransport | None = None,
    ) -> None:
        super().__init__(credentials)
        self._config = HolmesConfig.model_validate(config)
        # 原生 Holmes 服务可能自主运行工具。其工具隔离尚未接入本平台的
        # Dispatcher，当前只交付协议适配与 Fake；禁止实际发送 HTTP 请求。
        if transport is None:
            raise HolmesError("Holmes 原生工具隔离尚未验收，只允许 Fake 或 HTTP mock")
        assert self.reader_credentials is not None
        if self.reader_credentials.connector != "holmes":
            raise ValueError("Holmes 只接受独立的 holmes Reader 凭证")
        token = self.reader_credentials.token.get_secret_value()
        if any(char.isspace() or ord(char) < 32 for char in token):
            raise ValueError("Holmes Reader 凭证不能包含空白或控制字符")
        if transport is not None and not isinstance(transport, httpx.MockTransport):
            raise TypeError("测试只接受 MockTransport")
        self._http = httpx.AsyncClient(
            base_url=self._config.base_url,
            headers={"Authorization": f"Bearer {token}"},
            timeout=self._config.timeout_seconds,
            transport=transport,
            trust_env=False,
            follow_redirects=False,
        )

    async def analyze(self, request: HolmesRequest) -> HolmesResponse:
        request = HolmesRequest.model_validate(request)
        if self._http.is_closed:
            raise HolmesError("Holmes Connector 已关闭")
        payload = {
            "ask": request.model_dump_json(),
            "model": self._config.model,
            "stream": False,
            "enable_tool_approval": True,
            "additional_system_prompt": "仅分析给定证据快照，禁止调用任何工具。仅返回 JSON 意见。",
            "response_format": {
                "type": "json_schema",
                "json_schema": {"name": "expert_opinion", "schema": request.output_schema},
            },
        }
        try:
            response = await self._http.post("api/chat", json=payload)
            if not response.is_success:
                raise HolmesError("Holmes 返回非成功状态")
            body = json.loads(response.content)
            if (
                not isinstance(body, dict)
                or body.get("tool_calls")
                or body.get("approval_required")
            ):
                raise HolmesError("Holmes 响应试图运行工具")
            return HolmesResponse.model_validate({"analysis": body.get("analysis")})
        except HolmesError:
            raise
        except Exception:
            raise HolmesError("Holmes 快照分析失败") from None

    async def aclose(self) -> None:
        await self._http.aclose()

"""默认 Fake；local/test 禁止真实 Holmes 服务。"""

import httpx2 as httpx

from app.config import Settings
from app.connectors.factory import ConnectorFactory
from app.connectors.holmes.client import HolmesConnector, HTTPHolmesConnector
from app.connectors.holmes.fake import FakeHolmesConnector
from app.connectors.holmes.models import HolmesConfig
from app.connectors.models import ReaderCredentials


def create_holmes_connector(
    settings: Settings, *, transport: httpx.MockTransport | None = None
) -> HolmesConnector:
    config = Settings.model_validate(
        {
            field.validation_alias if isinstance(field.validation_alias, str) else name: getattr(
                settings, name
            )
            for name, field in Settings.model_fields.items()
        }
    )

    def real(credentials: ReaderCredentials) -> HolmesConnector:
        if config.holmes_config is None:
            raise ValueError("请通过环境变量设置 HOLMES_CONFIG")
        return HTTPHolmesConnector(
            HolmesConfig.model_validate(config.holmes_config), credentials, transport=transport
        )

    return ConnectorFactory[HolmesConnector]("holmes", fake=FakeHolmesConnector, real=real).create(
        config
    )

"""Fake Holmes 服务仅依据实际传入的快照生成意见。"""

import json

from app.connectors.holmes.client import HolmesConnector, HolmesError
from app.connectors.holmes.models import HolmesRequest, HolmesResponse


class FakeHolmesConnector(HolmesConnector):
    def __init__(self) -> None:
        super().__init__()
        self.calls: list[HolmesRequest] = []
        self.closed = False

    async def analyze(self, request: HolmesRequest) -> HolmesResponse:
        if self.closed:
            raise HolmesError("Fake Holmes 已关闭")
        request = HolmesRequest.model_validate_json(request.model_dump_json())
        self.calls.append(request)
        snapshots = request.context.get("evidence")
        if not isinstance(snapshots, list) or not snapshots:
            raise HolmesError("Holmes 缺少快照")
        ids = [item["id"] for item in snapshots if isinstance(item, dict) and "id" in item]
        return HolmesResponse(
            analysis=json.dumps(
                {
                    "assessment": {
                        "statement": f"{request.service_name} 快照提示需核查连接池与数据库容量。",
                        "evidence_ids": ids,
                    },
                    "findings": [],
                    "confidence": 0.65,
                    "uncertainties": ["这是快照 RCA 意见，仍需主 Agent 验证因果与替代原因。"],
                },
                ensure_ascii=False,
            )
        )

    async def aclose(self) -> None:
        self.closed = True

"""HolmesGPT 与本平台之间的快照意见契约。"""

from typing import Annotated, Literal
from urllib.parse import urlsplit

from pydantic import BaseModel, ConfigDict, Field, field_validator

from app.tools.models import JsonObject, ToolModel


class HolmesConfig(BaseModel):
    model_config = ConfigDict(frozen=True, extra="forbid", hide_input_in_errors=True)

    base_url: str
    model: str = Field(min_length=1)
    snapshot_only: Literal[True]
    timeout_seconds: float = Field(default=60, gt=0, le=300, allow_inf_nan=False)

    @field_validator("base_url")
    @classmethod
    def validate_url(cls, value: str) -> str:
        try:
            url = urlsplit(value)
            valid = (
                url.scheme in {"http", "https"}
                and bool(url.hostname)
                and url.port != 0
                and url.username is None
                and url.password is None
                and not url.query
                and not url.fragment
                and not any(char.isspace() for char in value)
            )
        except ValueError:
            valid = False
        if not valid:
            raise ValueError("HOLMES_CONFIG.base_url 必须是无凭证的 HTTP(S) 地址")
        return value.rstrip("/") + "/"

    @field_validator("model")
    @classmethod
    def model_name(cls, value: str) -> str:
        if not value.strip():
            raise ValueError("Holmes 模型配置名不能为空")
        return value


class HolmesRequest(ToolModel):
    service_name: str
    question: str
    context: JsonObject
    output_schema: JsonObject


class HolmesResponse(ToolModel):
    analysis: Annotated[str, Field(min_length=1, max_length=100000)]

