"""Fake 所有检查有明确测量和来源；可注入异常/缺数据/过期场景。"""

from datetime import UTC, datetime

from app.connectors.inspection.client import InspectionConnector
from app.connectors.inspection.models import InspectionFact, InspectionFacts, InspectionQuery
from app.tasks.inspection.catalog import CHECKS


def sample_facts(service: str, *, abnormal: bool = True) -> InspectionFacts:
    now = datetime.now(UTC)
    facts = []
    for check in CHECKS:
        value: bool | float
        if check.operator in {"true", "false"}:
            value = check.operator == "true"
        else:
            value = check.threshold + 10 if check.operator == "min" else 0.1
        if abnormal:
            value = {
                "pdb_present": False,
                "hpa_present": False,
                "certificate_days": 6.0,
                "ecs_idle": True,
            }.get(check.id, value)
        resource = "ecs-unused" if check.id == "ecs_idle" else service
        facts.append(
            InspectionFact(
                check_id=check.id,
                resource=resource,
                value=value,
                source_reference=f"fake://inspection/{service}/{check.id}/{resource}",
                observed_at=now,
            )
        )
    return InspectionFacts(service_name=service, complete=True, facts=tuple(facts))


class FakeInspectionConnector(InspectionConnector):
    def __init__(self, snapshot: InspectionFacts | None = None) -> None:
        super().__init__()
        self.snapshot = snapshot.model_copy(deep=True) if snapshot else None
        self.closed = False
        self.calls = 0

    async def query(self, query: InspectionQuery) -> InspectionFacts:
        query = InspectionQuery.model_validate(query)
        if self.closed:
            raise RuntimeError("Fake 巡检 Connector 已关闭")
        self.calls += 1
        result = self.snapshot or sample_facts(query.service_name)
        if result.service_name != query.service_name:
            raise ValueError("Fake 服务范围错误")
        return InspectionFacts.model_validate(result).model_copy(deep=True)

    async def aclose(self) -> None:
        self.closed = True

"""只保存测量值与来源引用，不复制原始指标、日志或凭证。"""

from datetime import UTC, datetime
from urllib.parse import urlsplit

from pydantic import AwareDatetime, Field, field_validator, model_validator

from app.connectors.kubernetes.models import ServiceName
from app.tools.models import ToolModel


class InspectionQuery(ToolModel):
    service_name: ServiceName


class InspectionFact(ToolModel):
    check_id: str = Field(pattern=r"^[a-z][a-z0-9_]{0,63}$")
    resource: str = Field(min_length=1, max_length=256, pattern=r"^\S+$")
    value: bool | float | None
    source_reference: str = Field(min_length=1, max_length=512, pattern=r"^\S+$")
    observed_at: AwareDatetime

    @field_validator("source_reference")
    @classmethod
    def safe_reference(cls, value: str) -> str:
        parsed = urlsplit(value)
        if (
            not parsed.scheme
            or not parsed.netloc
            or parsed.username is not None
            or parsed.password is not None
            or parsed.query
            or parsed.fragment
        ):
            raise ValueError("事实引用必须为无凭证或查询参数的来源 URI")
        return value

    @field_validator("value")
    @classmethod
    def finite(cls, value: bool | float | None) -> bool | float | None:
        import math

        if isinstance(value, float) and not math.isfinite(value):
            raise ValueError("巡检测量值必须有限")
        return value

    @field_validator("observed_at")
    @classmethod
    def utc(cls, value: datetime) -> datetime:
        return value.astimezone(UTC)


class InspectionFacts(ToolModel):
    service_name: ServiceName
    # complete=false 表示分页、范围或采集未完成，不能据此清除已有风险。
    complete: bool
    facts: tuple[InspectionFact, ...] = Field(max_length=5000)

    @model_validator(mode="after")
    def unique(self) -> "InspectionFacts":
        if len({(f.check_id, f.resource) for f in self.facts}) != len(self.facts):
            raise ValueError("同一检查和资源不能有冲突或重复观测")
        return self

"""标准 apps/v1 Deployment 和 core/v1 Pod/Event 只读 API；不自建重试或 Watch。"""

import ssl
from abc import abstractmethod

import httpx2 as httpx
from pydantic import TypeAdapter, ValidationError

from app.connectors.base import ReadOnlyConnector
from app.connectors.kubernetes.config import KubernetesConfig
from app.connectors.kubernetes.models import (
    Deployment,
    Event,
    Namespace,
    NamespaceRecord,
    Pod,
    ResourceList,
    ServiceName,
)
from app.connectors.kubernetes.watch import EventWatchBatch, read_event_watch
from app.connectors.models import ReaderCredentials

_namespace = TypeAdapter(Namespace)
_service = TypeAdapter(ServiceName)


def checked_query(namespace: str, service_name: str | None) -> None:
    _namespace.validate_python(namespace, strict=True)
    if service_name is not None:
        _service.validate_python(service_name, strict=True)


class KubernetesError(RuntimeError):
    """异常只输出固定消息，不带 token、URL 或源系统正文。"""


class KubernetesResponseError(KubernetesError):
    pass


class KubernetesTimeout(KubernetesError):
    pass


class KubernetesTransportError(KubernetesError):
    pass


class KubernetesHTTPError(KubernetesError):
    def __init__(self, status_code: int) -> None:
        self.status_code = status_code
        super().__init__(f"Kubernetes 返回 HTTP {status_code}")


def service_events(
    events: tuple[Event, ...], deployments: tuple[Deployment, ...], pods: tuple[Pod, ...]
) -> tuple[Event, ...]:
    objects: tuple[Deployment | Pod, ...] = (*deployments, *pods)
    targets = {
        (item.metadata.uid, item.kind, item.metadata.namespace, item.metadata.name)
        for item in objects
    }
    # Event 通常没有服务标签；必须用 UID，不能把同名旧 Pod 的 Event 归到新 Pod。
    return tuple(
        event
        for event in events
        if (
            event.involved_object.uid,
            event.involved_object.kind,
            event.involved_object.namespace,
            event.involved_object.name,
        )
        in targets
    )


class KubernetesConnector(ReadOnlyConnector):
    async def watch_events(
        self, namespace: str, *, resource_version: str = "", timeout_seconds: int = 20
    ) -> EventWatchBatch:
        raise NotImplementedError("该 Connector 未实现 Event Watch")

    @abstractmethod
    async def list_namespaces(self) -> tuple[str, ...]: ...

    @property
    @abstractmethod
    def cluster_name(self) -> str: ...

    @abstractmethod
    async def list_deployments(
        self, namespace: str, *, service_name: str | None = None
    ) -> tuple[Deployment, ...]: ...

    @abstractmethod
    async def list_pods(
        self, namespace: str, *, service_name: str | None = None
    ) -> tuple[Pod, ...]: ...

    @abstractmethod
    async def list_events(
        self, namespace: str, *, service_name: str | None = None
    ) -> tuple[Event, ...]: ...


class HTTPKubernetesConnector(KubernetesConnector):
    async def watch_events(
        self, namespace: str, *, resource_version: str = "", timeout_seconds: int = 20
    ) -> EventWatchBatch:
        checked_query(namespace, None)
        self._check_namespace(namespace)
        if type(timeout_seconds) is not int or not 1 <= timeout_seconds <= 60:
            raise ValueError("Watch 超时必须为 1–60 秒")
        if len(resource_version) > 256 or any(c.isspace() for c in resource_version):
            raise ValueError("Watch resourceVersion 无效")
        return await read_event_watch(
            self._http,
            namespace,
            resource_version,
            timeout_seconds,
            page_size=self._config.page_size,
            max_pages=self._config.max_pages,
        )

    def __init__(
        self,
        config: KubernetesConfig,
        credentials: ReaderCredentials,
        *,
        transport: httpx.MockTransport | None = None,
    ) -> None:
        super().__init__(credentials)
        assert self.reader_credentials is not None
        if self.reader_credentials.connector != "kubernetes":
            raise ValueError("Kubernetes 只接受 kubernetes 的 Reader 凭证")
        token = self.reader_credentials.token.get_secret_value()
        if any(char.isspace() or ord(char) < 32 for char in token):
            raise ValueError("Kubernetes Reader token 不能包含空白或控制字符")
        self._config = KubernetesConfig.model_validate(config)
        if transport is not None and not isinstance(transport, httpx.MockTransport):
            raise TypeError("测试 transport 只接受 MockTransport")
        context = ssl.create_default_context()
        if self._config.ca_cert_pem is not None:
            try:
                context.load_verify_locations(cadata=self._config.ca_cert_pem)
            except (ssl.SSLError, ValueError):
                raise ValueError("KUBERNETES_CONFIG.ca_cert_pem 必须是有效的 PEM CA 证书") from None
        self._http = httpx.AsyncClient(
            base_url=self._config.base_url,
            headers={"Authorization": f"Bearer {token}", "Accept": "application/json"},
            timeout=self._config.timeout_seconds,
            verify=context,
            transport=transport,
            trust_env=False,
            follow_redirects=False,
        )

    @property
    def cluster_name(self) -> str:
        return self._config.cluster_name

    async def aclose(self) -> None:
        await self._http.aclose()

    def _check_namespace(self, namespace: str) -> None:
        allowed = self._config.namespace_allowlist
        if allowed is not None and namespace not in allowed:
            raise KubernetesError("命名空间不在 Reader 授权白名单内")

    async def _read[Record: Deployment | Pod | Event | NamespaceRecord](
        self,
        namespace: str | None,
        service_name: str | None,
        page_type: type[ResourceList[Record]],
        *,
        path: str,
        api_version: str,
        kind: str,
    ) -> tuple[Record, ...]:
        if self._http.is_closed:
            raise KubernetesError("Kubernetes Connector 已关闭")
        if namespace is not None:
            checked_query(namespace, service_name)
            self._check_namespace(namespace)
        query = {"limit": str(self._config.page_size)}
        if service_name is not None:
            query["labelSelector"] = f"{self._config.service_label_key}={service_name}"
        items: list[Record] = []
        seen_uids: set[str] = set()
        seen_names: set[str] = set()
        seen_cursors: set[str] = set()
        resource_version: str | None = None
        for page_index in range(self._config.max_pages):
            try:
                response = await self._http.get(path, params=query)
            except httpx.TimeoutException:
                raise KubernetesTimeout("Kubernetes 读取超时") from None
            except httpx.RequestError:
                raise KubernetesTransportError("Kubernetes 连接失败") from None
            if response.status_code != 200:
                raise KubernetesHTTPError(response.status_code)
            try:
                page = page_type.model_validate_json(response.content)
            except (ValidationError, ValueError):
                raise KubernetesResponseError("Kubernetes 响应不符合只读 API 协议") from None
            if page.api_version != api_version or page.kind != kind + "List":
                raise KubernetesResponseError("Kubernetes 返回的资源列表类型不符")
            if page_index == 0:
                resource_version = page.metadata.resource_version
            elif page.metadata.resource_version != resource_version:
                raise KubernetesResponseError("Kubernetes 分页资源版本不一致")
            for item in page.items:
                meta = item.metadata
                if (namespace is not None and getattr(meta, "namespace", None) != namespace) or (
                    service_name is not None
                    and getattr(meta, "labels", {}).get(self._config.service_label_key)
                    != service_name
                ):
                    raise KubernetesResponseError("Kubernetes 响应与命名空间/服务筛选条件不符")
                if meta.uid in seen_uids or meta.name in seen_names:
                    raise KubernetesResponseError("Kubernetes 分页出现重复对象")
                seen_uids.add(meta.uid)
                seen_names.add(meta.name)
                items.append(item)
            cursor = page.metadata.continue_token
            if not cursor:
                return tuple(items)
            if cursor in seen_cursors:
                raise KubernetesResponseError("Kubernetes 分页游标重复")
            seen_cursors.add(cursor)
            query["continue"] = cursor
        raise KubernetesResponseError("Kubernetes 读取超出分页上限，结果不完整")

    async def list_namespaces(self) -> tuple[str, ...]:
        records = await self._read(
            None,
            None,
            ResourceList[NamespaceRecord],
            path="api/v1/namespaces",
            api_version="v1",
            kind="Namespace",
        )
        names = tuple(record.metadata.name for record in records)
        allowed = self._config.namespace_allowlist
        if allowed is not None:
            if set(allowed) - set(names):
                raise KubernetesResponseError("Reader 配置的命名空间不存在")
            return tuple(name for name in names if name in allowed)
        return names

    async def list_deployments(
        self, namespace: str, *, service_name: str | None = None
    ) -> tuple[Deployment, ...]:
        checked_query(namespace, service_name)
        return await self._read(
            namespace,
            service_name,
            ResourceList[Deployment],
            path=f"apis/apps/v1/namespaces/{namespace}/deployments",
            api_version="apps/v1",
            kind="Deployment",
        )

    async def list_pods(
        self, namespace: str, *, service_name: str | None = None
    ) -> tuple[Pod, ...]:
        checked_query(namespace, service_name)
        return await self._read(
            namespace,
            service_name,
            ResourceList[Pod],
            path=f"api/v1/namespaces/{namespace}/pods",
            api_version="v1",
            kind="Pod",
        )

    async def list_events(
        self, namespace: str, *, service_name: str | None = None
    ) -> tuple[Event, ...]:
        checked_query(namespace, service_name)
        deployments = (
            await self.list_deployments(namespace, service_name=service_name)
            if service_name is not None
            else ()
        )
        pods = (
            await self.list_pods(namespace, service_name=service_name)
            if service_name is not None
            else ()
        )
        events = await self._read(
            namespace,
            None,
            ResourceList[Event],
            path=f"api/v1/namespaces/{namespace}/events",
            api_version="v1",
            kind="Event",
        )
        return service_events(events, deployments, pods) if service_name is not None else events

"""显式配置 ACK/K8s API 和服务标签；身份只来自环境变量。"""

import re
from urllib.parse import urlsplit

from pydantic import BaseModel, ConfigDict, Field, field_validator

from app.connectors.kubernetes.models import Namespace


class KubernetesConfig(BaseModel):
    model_config = ConfigDict(
        frozen=True, extra="forbid", revalidate_instances="always", hide_input_in_errors=True
    )
    cluster_name: str = Field(min_length=1, max_length=256, pattern=r"^\S+$")
    base_url: str
    service_label_key: str = "app.kubernetes.io/name"
    ca_cert_pem: str | None = Field(default=None, repr=False)
    timeout_seconds: float = Field(default=15, gt=0, le=120, allow_inf_nan=False)
    page_size: int = Field(default=100, ge=1, le=500)
    max_pages: int = Field(default=100, ge=1, le=1000)
    namespace_allowlist: tuple[Namespace, ...] | None = Field(
        default=None, min_length=1, max_length=1000
    )

    @field_validator("namespace_allowlist")
    @classmethod
    def unique_namespaces(cls, value: tuple[str, ...] | None) -> tuple[str, ...] | None:
        if value is not None and len(set(value)) != len(value):
            raise ValueError("命名空间白名单不能重复")
        return value

    @field_validator("base_url")
    @classmethod
    def validate_url(cls, value: str) -> str:
        try:
            url = urlsplit(value)
            valid = (
                url.scheme == "https"
                and bool(url.hostname)
                and url.port != 0
                and url.username is None
                and url.password is None
                and not url.query
                and not url.fragment
                and url.path in {"", "/"}
                and not any(char.isspace() or ord(char) < 32 for char in value)
                and "\\" not in value
            )
        except ValueError:
            valid = False
        if not valid:
            raise ValueError("KUBERNETES_CONFIG.base_url 必须是无凭证、无路径的 HTTPS API 地址")
        return value.rstrip("/") + "/"

    @field_validator("service_label_key")
    @classmethod
    def validate_label_key(cls, value: str) -> str:
        parts = value.split("/")
        name = parts[-1]
        valid = (
            len(parts) <= 2
            and len(name) <= 63
            and re.fullmatch(r"[A-Za-z0-9]([-A-Za-z0-9_.]*[A-Za-z0-9])?", name) is not None
        )
        if len(parts) == 2:
            valid = (
                valid
                and len(parts[0]) <= 253
                and all(
                    len(segment) <= 63 and re.fullmatch(r"[a-z0-9]([-a-z0-9]*[a-z0-9])?", segment)
                    for segment in parts[0].split(".")
                )
            )
        if not valid:
            raise ValueError("KUBERNETES_CONFIG.service_label_key 必须是合法的 Kubernetes 标签键")
        return value

"""独立写入通道：动作级授权服务契约，Fake 实施精确参数限制和幂等执行。

原生 RBAC 无法限制同一资源的具体参数，不能将普通 SA token 包装为动作级权限。
HTTP 端须由已有运维平台的受信动作端实施同等限制；当前只开放 MockTransport。
"""

import secrets
from abc import ABC, abstractmethod
from collections.abc import Callable
from datetime import UTC, datetime, timedelta
from typing import Self
from uuid import UUID

import httpx2 as httpx
from pydantic import AwareDatetime, Field, SecretStr, field_validator, model_validator

from app.connectors.kubernetes.config import KubernetesConfig
from app.connectors.models import (
    ExecutorCredentials,
    ReaderCredentials,
    validate_credential_separation,
)
from app.db.base import utc_now
from app.executor.models import (
    ExecutionBinding,
    ExecutionCommand,
    ExecutionTarget,
    TargetQuery,
    command_hash,
)
from app.tools.models import ToolModel


class ActionCredential(ToolModel):
    token: SecretStr = Field(repr=False)
    execution_id: UUID
    command_hash: str = Field(pattern=r"^[0-9a-f]{64}$")
    issued_at: AwareDatetime
    expires_at: AwareDatetime

    @field_validator("issued_at", "expires_at")
    @classmethod
    def utc_times(cls, value: datetime) -> datetime:
        return value.astimezone(UTC)

    @model_validator(mode="after")
    def short_lived(self) -> "ActionCredential":
        duration = (self.expires_at - self.issued_at).total_seconds()
        if not 0 < duration <= 300 or not self.token.get_secret_value().strip():
            raise ValueError("动作凭证必须非空且至多有效 300 秒")
        return self


class ExecutionReceipt(ToolModel):
    execution_id: UUID
    command_hash: str = Field(pattern=r"^[0-9a-f]{64}$")
    completed_at: AwareDatetime
    target: ExecutionTarget

    @field_validator("completed_at")
    @classmethod
    def utc_completion(cls, value: datetime) -> datetime:
        return value.astimezone(UTC)


def validate_capability(
    command: ExecutionCommand, credential: ActionCredential, now: datetime
) -> None:
    credential = ActionCredential.model_validate(credential)
    if now.tzinfo is None or not (
        credential.execution_id == command.execution_id
        and credential.command_hash == command_hash(command)
        and credential.issued_at <= now < credential.expires_at
    ):
        raise PermissionError("动作凭证过期或超出精确动作范围")


class KubernetesWriteConnector(ABC):
    async def __aenter__(self) -> Self:
        return self

    async def __aexit__(self, *args: object) -> None:
        await self.aclose()

    @abstractmethod
    async def inspect(self, binding: TargetQuery) -> ExecutionTarget: ...

    @abstractmethod
    async def issue(self, command: ExecutionCommand, ttl_seconds: int) -> ActionCredential: ...

    @abstractmethod
    async def execute(
        self, command: ExecutionCommand, credential: ActionCredential
    ) -> ExecutionReceipt: ...

    @abstractmethod
    async def aclose(self) -> None: ...


def fake_binding() -> ExecutionBinding:
    return ExecutionBinding(
        service_name="payment-service",
        cluster_name="ack-fake",
        namespace="payment",
        deployment_name="payment-service",
        container_name="payment",
        images={v: f"registry.example.invalid/payment:{v}" for v in ("v2.3.6", "v2.3.7")},
    )


class FakeKubernetesWriteConnector(KubernetesWriteConnector):
    def __init__(self, *, clock: Callable[[], datetime] = utc_now) -> None:
        binding = fake_binding()
        self.targets = {
            binding.service_name: ExecutionTarget(
                service_name=binding.service_name,
                cluster_name=binding.cluster_name,
                namespace=binding.namespace,
                deployment_name=binding.deployment_name,
                container_name=binding.container_name,
                uid="deployment-payment",
                resource_version="7",
                image=binding.images["v2.3.7"],
                replicas=3,
            )
        }
        self.clock = clock
        self.credentials: dict[str, ActionCredential] = {}
        self.receipts: dict[UUID, ExecutionReceipt] = {}
        self.execution_count = 0
        self.issue_count = 0
        self.closed = False

    def check_open(self) -> None:
        if self.closed:
            raise RuntimeError("动作 Connector 已关闭")

    async def inspect(self, binding: TargetQuery) -> ExecutionTarget:
        self.check_open()
        target = self.targets[binding.service_name]
        if any(
            getattr(target, f) != getattr(binding, f)
            for f in ("cluster_name", "namespace", "deployment_name", "container_name")
        ):
            raise ValueError("执行目标与服务绑定不一致")
        return target.model_copy(deep=True)

    async def issue(self, command: ExecutionCommand, ttl_seconds: int) -> ActionCredential:
        self.check_open()
        if type(ttl_seconds) is not int or not 1 <= ttl_seconds <= 300:
            raise ValueError("动作凭证有效期必须为 1–300 秒")
        command = ExecutionCommand.model_validate(command)
        now = self.clock().astimezone(UTC)
        self.credentials = {
            token: issued for token, issued in self.credentials.items() if issued.expires_at > now
        }
        credential = ActionCredential(
            token=SecretStr(secrets.token_urlsafe(32)),
            execution_id=command.execution_id,
            command_hash=command_hash(command),
            issued_at=now,
            expires_at=now + timedelta(seconds=ttl_seconds),
        )
        self.credentials[credential.token.get_secret_value()] = credential.model_copy(deep=True)
        self.issue_count += 1
        return credential

    async def execute(
        self, command: ExecutionCommand, credential: ActionCredential
    ) -> ExecutionReceipt:
        self.check_open()
        command = ExecutionCommand.model_validate(command)
        credential = ActionCredential.model_validate(credential)
        validate_capability(command, credential, self.clock())
        if self.credentials.get(credential.token.get_secret_value()) != credential:
            raise PermissionError("动作凭证不是由受信签发端签发")
        previous = self.receipts.get(command.execution_id)
        if previous:
            if previous.command_hash != command_hash(command):
                raise PermissionError("相同幂等键不能用于其他动作")
            return previous.model_copy(deep=True)
        target = self.targets.get(command.target.service_name)
        if target != command.target:
            raise ValueError("资源已变更或目标不符，拒绝过期动作")
        target = target.model_copy(
            update={
                "image": command.expected_image,
                "replicas": command.expected_replicas,
                "resource_version": str(int(target.resource_version) + 1),
                "paused": target.paused
                if command.expected_paused is None
                else command.expected_paused,
                "traffic_percent": target.traffic_percent
                if command.expected_traffic_percent is None
                else command.expected_traffic_percent,
            }
        )
        receipt = ExecutionReceipt(
            execution_id=command.execution_id,
            command_hash=command_hash(command),
            completed_at=self.clock().astimezone(UTC),
            target=target,
        )
        self.targets[target.service_name] = target
        self.receipts[command.execution_id] = receipt
        self.execution_count += 1
        return receipt.model_copy(deep=True)

    async def aclose(self) -> None:
        self.closed = True
        self.credentials.clear()


class HTTPKubernetesWriteConnector(KubernetesWriteConnector):
    """已有动作端的显式 GET/POST 协议；签发身份与 Reader 分离。

    服务端须实施精确命令哈希/目标/有效期及持久化 execution_id 去重。
    不使用该 token 访问原生 Kubernetes API，也不自行构造真实生产权限。
    """

    def __init__(
        self,
        config: KubernetesConfig,
        reader: ReaderCredentials,
        executor: ExecutorCredentials,
        *,
        transport: httpx.MockTransport | None = None,
    ) -> None:
        validate_credential_separation(reader, executor)
        if reader.connector != "kubernetes":
            raise ValueError("动作通道需要 Kubernetes 身份")
        if transport is None or not isinstance(transport, httpx.MockTransport):
            raise ValueError("真实动作端协议与服务器参数限制尚未验收；只允许 HTTP mock")
        config = KubernetesConfig.model_validate(config)
        self.reader, self.executor = reader, executor
        self.http = httpx.AsyncClient(
            base_url=config.base_url,
            transport=transport,
            timeout=config.timeout_seconds,
            trust_env=False,
            follow_redirects=False,
        )

    async def request(self, method: str, path: str, token: SecretStr, payload: object) -> object:
        try:
            response = await self.http.request(
                method,
                path,
                json=payload,
                headers={"Authorization": f"Bearer {token.get_secret_value()}"},
            )
            if response.status_code != 200:
                raise RuntimeError("动作端响应失败")
            return response.json()
        except Exception:
            raise RuntimeError("动作端请求失败，需按幂等键核对结果") from None

    async def inspect(self, binding: TargetQuery) -> ExecutionTarget:
        return ExecutionTarget.model_validate_json(
            json_encode(
                await self.request(
                    "POST", "execution/inspect", self.reader.token, binding.model_dump(mode="json")
                )
            )
        )

    async def issue(self, command: ExecutionCommand, ttl_seconds: int) -> ActionCredential:
        if type(ttl_seconds) is not int or not 1 <= ttl_seconds <= 300:
            raise ValueError("动作凭证有效期必须为 1–300 秒")
        credential = ActionCredential.model_validate_json(
            json_encode(
                await self.request(
                    "POST",
                    "execution/credentials",
                    self.executor.token,
                    {"command": command.model_dump(mode="json"), "ttl_seconds": ttl_seconds},
                )
            )
        )
        validate_capability(command, credential, utc_now())
        if (credential.expires_at - credential.issued_at).total_seconds() > ttl_seconds:
            raise PermissionError("动作端签发的凭证超过请求有效期")
        if credential.token in {self.reader.token, self.executor.token}:
            raise PermissionError("动作凭证不可复用 Reader 或签发身份")
        return credential

    async def execute(
        self, command: ExecutionCommand, credential: ActionCredential
    ) -> ExecutionReceipt:
        validate_capability(command, credential, utc_now())
        receipt = ExecutionReceipt.model_validate_json(
            json_encode(
                await self.request(
                    "POST", "execution/actions", credential.token, command.model_dump(mode="json")
                )
            )
        )
        if (
            receipt.command_hash != command_hash(command)
            or receipt.execution_id != command.execution_id
        ):
            raise ValueError("动作回执与请求不符")
        return receipt

    async def aclose(self) -> None:
        await self.http.aclose()


def json_encode(value: object) -> str:
    import json

    return json.dumps(value)

